"""
    >>> has_a_double_not_in_larger_group('1234')
    False
    >>> has_a_double_not_in_larger_group('111123')
    False
    >>> has_a_double_not_in_larger_group('135679')
    False
    >>> has_a_double_not_in_larger_group('223450')
    True
    >>> has_a_double_not_in_larger_group('111111')
    False
    >>> has_a_double_not_in_larger_group('123789')
    False
    >>> has_a_double_not_in_larger_group('112233')
    True
    >>> has_a_double_not_in_larger_group('123444')
    False
    >>> has_a_double_not_in_larger_group('111122')
    True
    """
def has_a_double_not_in_larger_group(s: Any) -> object {
    l = [int(c) for c in s];
    while (len(l) > 0) {
        current_l = [];
        current_l.append(l.pop(0));
        while (len(l) > 0) {
            if (l[0] == current_l[0]) {
                current_l.append(l.pop(0));
            } else {
                break;
            }
        }
        if (len(current_l) == 2) {
            return True;
        }
    }
    return False;
}

"""Return a matrix as a matrix-multiplication of X_M and arbitary number of matrices *Y_M"""
def matrix_multiplication(X_M: Any, *Y_M: Any) -> object {
    """Return a matrix as a matrix-multiplication of two matrices X_M and Y_M
        >>> matrix_multiplication([[1, 2, 3],
                                   [2, 3, 4]],
                                   [[3, 4],
                                    [1, 2],
                                    [1, 0]])
        [[8, 8],[13, 14]]
        """;
    def _mat_mult(X_M: Any, Y_M: Any) -> object {
        assert (len(X_M[0]) == len(Y_M));
        result = [[0 for i in range(len(Y_M[0]))] for j in range(len(X_M))];
        for i in range(len(X_M)) {
            for j in range(len(Y_M[0])) {
                for k in range(len(Y_M)) {
                    result[i][j] += X_M[i][k] * Y_M[k][j];
                }
            }
        }
        return result;
    }
    result = X_M;
    for Y in Y_M {
        result = _mat_mult(result, Y);
    }
    return result;
}

"""Generate a number in the range [0, num_buckets).

    Args:
        key (int): The key to hash.
        num_buckets (int): Number of buckets to use.

    Returns:
        The bucket number `key` computes to.

    Raises:
        ValueError: If `num_buckets` is not a positive number.
    """
def py_hash(key: Any, num_buckets: Any) -> object {
    (b, j) = (-1, 0.0);
    if (num_buckets < 1) {
        raise ValueError(f"'num_buckets' must be a positive number, got {num_buckets}");
    }
    while (j < num_buckets) {
        b = int(j);
        key = ((key * int(2862933555777941757)) + 1) & 18446744073709551615;
        j = float((b + 1)) * (float((1 << 31)) / float(((key >> 33) + 1)));
    }
    return int(b);
}

